using System;using UnityEditor;using UnityEngine;
namespace XuanwuTools { public static class SnowMaskGenerator {
 [Serializable] class Config {public string scenePath;public int snowLayer,rockLayer;public float startAngle=20,endAngle=55;public int seed=17;}
 [MenuItem(Common.Menu+"08 Paint slope snow JSON")] public static void Paint()=>Common.Run(()=>{var c=Common.Read<Config>();Common.SceneGuard(c.scenePath);var t=Common.SelectedTerrain();var d=t.terrainData;int n=d.alphamapResolution;if(n>1024||d.alphamapLayers!=2||c.snowLayer<0||c.rockLayer<0||c.snowLayer>1||c.rockLayer>1||c.rockLayer==c.snowLayer||c.startAngle<0||c.endAngle<=c.startAngle||c.endAngle>90)throw new Exception("Requires exactly two assigned layers and <=1024 alphamap; valid angles");var a=new float[n,n,2];for(int z=0;z<n;z++)for(int x=0;x<n;x++){float u=x/(float)(n-1),v=z/(float)(n-1);float angle=d.GetSteepness(u,v)+(Mathf.PerlinNoise(u*20+c.seed,v*20)-.5f)*8;float s=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(c.startAngle,c.endAngle,angle));a[z,x,c.snowLayer]=s;a[z,x,c.rockLayer]=1-s;}if(!Common.Confirm("Snow mask dry-run","Clone selected TerrainData and replace both layer weights on whole tile? Not for protected hand-painted areas or shell."))return;var copy=Common.CloneData(t);copy.SetAlphamaps(0,0,a);EditorUtility.SetDirty(copy);AssetDatabase.SaveAssetIfDirty(copy);});}}
